app.post("/api/grammar/analyze", async (req, res) => {
  try {
    const { sentence, grammarStructure } = req.body;
    if (!sentence) {
      return res.status(400).json({ error: "sentence is required" });
    }
    const cacheKey = `${sentence.trim()}_${grammarStructure || ""}`;
    if (GRAMMAR_ANALYSIS_CACHE.has(cacheKey)) {
      return res.json(GRAMMAR_ANALYSIS_CACHE.get(cacheKey));
    }
    let ai;
    try {
      ai = getGeminiClient();
    } catch (err) {
      const fallback2 = analyzeOfflineGrammar(sentence, grammarStructure);
      return res.json(fallback2);
    }
    const systemInstruction = `B\u1EA1n l\xE0 m\u1ED9t chuy\xEAn gia ng\xF4n ng\u1EEF h\u1ECDc ti\u1EBFng Nh\u1EADt. Nhi\u1EC7m v\u1EE5 c\u1EE7a b\u1EA1n l\xE0 ph\xE2n t\xEDch c\u1EA5u tr\xFAc c\u1EE7a m\u1ED9t c\xE2u ti\u1EBFng Nh\u1EADt do ng\u01B0\u1EDDi d\xF9ng nh\u1EADp v\xE0o.
N\u1EBFu c\xF3 cung c\u1EA5p ng\u1EEF ph\xE1p m\u1EE5c ti\xEAu, h\xE3y t\u1EADp trung gi\u1EA3i th\xEDch c\xE1ch ng\u1EEF ph\xE1p \u0111\xF3 \u0111\u01B0\u1EE3c s\u1EED d\u1EE5ng trong c\xE2u.
H\xE3y chia c\xE2u th\xE0nh c\xE1c th\xE0nh ph\u1EA7n (ch\u1EE7 ng\u1EEF, v\u1ECB ng\u1EEF, b\u1ED5 ng\u1EEF, tr\u1EE3 t\u1EEB...) v\xE0 gi\u1EA3i th\xEDch chi ti\u1EBFt ch\u1EE9c n\u0103ng c\u1EE7a t\u1EEBng ph\u1EA7n.
B\u1EA1n b\u1EAFt bu\u1ED9c ph\u1EA3i tr\u1EA3 v\u1EC1 JSON \u0111\xFAng chu\u1EA9n v\u1EDBi c\u1EA5u tr\xFAc sau:
{
  "translation": "B\u1EA3n d\u1ECBch ti\u1EBFng Vi\u1EC7t c\u1EE7a c\xE2u",
  "romaji": "Phi\xEAn \xE2m romaji c\u1EE7a to\xE0n b\u1ED9 c\xE2u",
  "analysis": [
    {
      "part": "Th\xE0nh ph\u1EA7n c\xE2u (v\xED d\u1EE5: \u79C1, \u306F, \u65E5\u672C\u8A9E, \u3092, \u52C9\u5F37\u3057\u3066\u3044\u307E\u3059)",
      "type": "Lo\u1EA1i t\u1EEB/Th\xE0nh ph\u1EA7n (v\xED d\u1EE5: Ch\u1EE7 ng\u1EEF, Tr\u1EE3 t\u1EEB, Danh t\u1EEB, \u0110\u1ED9ng t\u1EEB)",
      "explanation": "Gi\u1EA3i th\xEDch chi ti\u1EBFt ch\u1EE9c n\u0103ng ng\u1EEF ph\xE1p v\xE0 \xFD ngh\u0129a"
    }
  ],
  "overallGrammar": "Nh\u1EADn x\xE9t t\u1ED5ng quan v\u1EC1 c\u1EA5u tr\xFAc ng\u1EEF ph\xE1p ch\xEDnh c\u1EE7a c\xE2u"
}`;
    const prompt = `H\xE3y ph\xE2n t\xEDch chi ti\u1EBFt c\xE2u ti\u1EBFng Nh\u1EADt sau: "${sentence}".${grammarStructure ? ` Ch\xFA \xFD \u0111\u1EB7c bi\u1EC7t \u0111\u1EBFn c\u1EA5u tr\xFAc ng\u1EEF ph\xE1p "${grammarStructure}".` : ""}`;
    let openAiErrorMsg = null;
    if (getActiveOpenAIApiKey()) {
      try {
        const rawJson = await callOpenAIGPT({
          prompt: prompt + "\nB\u1EAET BU\u1ED8C TR\u1EA2 V\u1EC0 \u0110\u1ECANH D\u1EA0NG JSON H\u1EE2P L\u1EC6 DUY NH\u1EA4T.",
          systemInstruction,
          model: getActiveOpenAIModel(),
          jsonMode: true
        });
        if (rawJson) {
          const parsed = JSON.parse(rawJson.trim());
          if (parsed && (parsed.translation || parsed.analysis)) {
            parsed.aiProvider = "chatgpt";
            parsed.modelUsed = `ChatGPT (${getActiveOpenAIModel()})`;
            GRAMMAR_ANALYSIS_CACHE.set(cacheKey, parsed);
            return res.json(parsed);
          }
        }
      } catch (openAiErr) {
        openAiErrorMsg = openAiErr?.message || String(openAiErr);
        console.warn("[ChatGPT grammar analyze error]:", openAiErrorMsg);
      }
    }
    try {
      const response = await generateGeminiContentWithFallback({
        model: LATEST_GEMINI_MODEL,
        contents: prompt,
        config: {
          systemInstruction,
          responseMimeType: "application/json",
          responseSchema: {
            type: import_genai3.Type.OBJECT,
            properties: {
              translation: { type: import_genai3.Type.STRING },
              romaji: { type: import_genai3.Type.STRING },
              analysis: {
                type: import_genai3.Type.ARRAY,
                items: {
                  type: import_genai3.Type.OBJECT,
                  properties: {
                    part: { type: import_genai3.Type.STRING },
                    type: { type: import_genai3.Type.STRING },
                    explanation: { type: import_genai3.Type.STRING }
                  },
                  required: ["part", "type", "explanation"]
                }
              },
              overallGrammar: { type: import_genai3.Type.STRING }
            },
            required: ["translation", "romaji", "analysis", "overallGrammar"]
          }
        }
      });
      const resultText = response.text;
      if (resultText) {
        const analysisResult = JSON.parse(resultText.trim());
        analysisResult.aiProvider = openAiErrorMsg ? "gemini_fallback" : "gemini";
        if (openAiErrorMsg) {
          analysisResult.openAiError = openAiErrorMsg.includes("429") || openAiErrorMsg.includes("credits") ? "T\xE0i kho\u1EA3n OpenAI (ChatGPT) hi\u1EC7n h\u1EBFt credits, h\u1EC7 th\u1ED1ng t\u1EF1 \u0111\u1ED9ng d\xF9ng Gemini AI ph\xE2n t\xEDch c\xE2u cho b\u1EA1n." : openAiErrorMsg;
        }
        GRAMMAR_ANALYSIS_CACHE.set(cacheKey, analysisResult);
        return res.json(analysisResult);
      }
    } catch (aiErr) {
      console.warn("Gemini grammar analyze fallback activated:", aiErr?.message || aiErr);
    }
    const fallback = analyzeOfflineGrammar(sentence, grammarStructure);
    fallback.aiProvider = "offline";
    if (openAiErrorMsg) fallback.openAiError = openAiErrorMsg;
    GRAMMAR_ANALYSIS_CACHE.set(cacheKey, fallback);
    res.json(fallback);
  } catch (error) {
    const fallback = analyzeOfflineGrammar(req.body.sentence, req.body.grammarStructure);
    res.json(fallback);
  }
});
