    const prompt = `H\xE3y ph\xE2n t\xEDch chi ti\u1EBFt v\xE0 d\u1EA1y ng\u1EAFt c\xE2u d\xE0i cho c\xE2u ti\u1EBFng Nh\u1EADt sau: "${sentence.trim()}"`;
